{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"xl","align":"center"},"children":["composer"]}}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"A day-by-day plan that fits your budget","lede":"Lay out the where-and-when, who's coming, and what you have to spend.","runLabel":"Plan my trip","columns":"2"},"children":["group-trip","group-who","group-budget","group-else"],"on":{"press":[{"action":"validateForm"},{"action":"run"}]}}}
