{"op":"add","path":"/elements/trip-dates","value":{"type":"DateRange","props":{"label":"Dates","from":{"$bindState":"/inputs/request/stay/arriving_on"},"to":{"$bindState":"/inputs/request/stay/leaving_on"}}},"children":[]}
