{"op":"add","path":"/elements/travellers-list","value":{"type":"CompactList","props":{"label":"Travellers","items":{"$bindState":"/inputs/request/travellers"},"primary":"name","secondary":["age","dietary"],"addLabel":"Add traveller"}},"children":[]}
{"op":"add","path":"/elements/group-budget","value":{"type":"FieldGroup","props":{"title":"Budget & style"},"children":["budget-amount","budget-currency","budget-pace","budget-style","budget-children","budget-accessibility"]}}
